//! Emit the SINGLE `@generated` TMS type catalogue — concrete Rust structs + enums (one per IDL
//! type), each with `serde` derives + (for `@topic` types) a `TmsTopic` impl; the flat `WireFlat`
//! MCU serializers; the 1-byte `TmsTopicId` topic index; and the `TmsMessage` dispatch factory.
//! Output goes through `prettyplease` (rustfmt-clean).
//!
//! This REPLACES the reflective `const` descriptor registry + `DynamicValue` codec. The output looks
//! like the hand-written schema types this replaces, but is machine-generated from the IDL — no drift.
//!
//! Struct Rust NAMES never appear in the JSON (only field names + enum renames do), so a name is
//! chosen for uniqueness + ergonomics: the bare IDL name, except the six `ac`/`dc`-colliding names
//! get a `Dc`/`Ac` prefix (`dc::MeasurementUpdate` -> `DcMeasurementUpdate`, matching the topic +
//! the golden type). Enum VARIANT wire spellings ARE the JSON, so each carries `#[serde(rename)]`
//! with the exact IDL enumerator (`SEV_7_MAJOR`, the preserved typo `FMI_ABNORMAL_RATE_OF_CHARGE`).

use std::collections::{HashMap, HashSet};

use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::quote;

use crate::model::{Model, RField, RFieldType, RKind, RType};
use crate::overrides::Overrides;

/// Emit the `lib-tms` `@generated` file: the IDL typedefs (named aliases) + concrete structs/enums
/// (with serde derives + `TmsTopic` impls) + the `TmsTopicId` topic index + the `TmsMessage` factory.
/// NO encoders, NO `JsonSink`/canonical dependency — those all live in the `lib-mapping` file
/// [`emit_encoders::emit_mapping`] so this crate stays a leaf.
pub fn emit_tms(model: &Model, overrides: &Overrides) -> Result<String, String> {
    // Guard: the manifest's MCU encoder subset is exactly what emit_encoders generates.
    let want = [
        "DcMeasurementUpdate",
        "PowerHardwareUpdate",
        "ActiveDiagnosticState",
    ];
    for w in want {
        if !overrides.subset.mcu_encoder_topics.iter().any(|t| t == w) {
            return Err(format!("manifest [subset] missing MCU encoder topic {w}"));
        }
    }

    let colliding = colliding_names(model);
    let typedefs = emit_typedefs(model);

    // Enums first, then structs (+ TmsTopic impls).
    let mut enum_items = Vec::new();
    let mut struct_items = Vec::new();
    for t in &model.types {
        match t.kind {
            RKind::Enum => enum_items.push(emit_enum(t, &colliding)),
            RKind::Struct => struct_items.push(emit_struct(t, &colliding)?),
        }
    }

    let topic_id = emit_topic_id(model)?;
    let factory = emit_factory(model, &colliding)?;

    let items = quote! {
        use serde::{Deserialize, Serialize};
        use crate::TmsTopic;
        #[cfg(feature = "std")]
        use crate::DecodeError;

        #typedefs
        #(#enum_items)*
        #(#struct_items)*
        #topic_id
        #factory
    };

    let file =
        syn::parse2::<syn::File>(items).map_err(|e| format!("emitted catalogue invalid: {e}"))?;
    let formatted = prettyplease::unparse(&file);
    Ok(format!(
        "// @generated by tms-idl-codegen — DO NOT EDIT.\n\
         //! Generated TMS (MIL-STD-3071) type catalogue — the IDL typedefs (named aliases) +\n\
         //! concrete structs + enums with serde derives, `TmsTopic` impls, the `TmsTopicId` topic\n\
         //! index, and the host-only `TmsMessage` serde dispatch factory.\n\
         //!\n\
         //! Source: `docs/compliance/tms/mil-std-3071_data_model.idl` (MIL-STD-3071 TMS 2.0.2).\n\
         //! Regenerate with `just tms-codegen`; `just tms-codegen-check` fails if this file is stale.\n\
         //!\n\
         //! The canonical->wire flat encoders are generated into\n\
         //! `lib-mapping/src/wire/generated_encoders.rs` (they need `JsonSink` + the canonical\n\
         //! model, which must NOT be dependencies of this leaf crate).\n\
         #![allow(clippy::all)]\n\
         #![allow(rustdoc::all)]\n\
         #![cfg_attr(rustfmt, rustfmt::skip)]\n\n{formatted}"
    ))
}

// ---- typedefs (named aliases) ------------------------------------------------------------------

/// Emit the KEPT IDL typedefs as named `pub type` aliases (`pub type Identity = heapless::String<32>;`
/// …). Consumers import these by name (`lib_tms::Identity`); the generated struct FIELDS still inline
/// the resolved leaf type (identical serde output either way). The `PowerPortNumber` sentinel
/// `INVALID_PORT_NUMBER` is emitted alongside its type (the standard's documented -1 sentinel).
fn emit_typedefs(model: &Model) -> TokenStream {
    let aliases = model.typedefs.iter().map(|td| {
        let name = ty_ident(&td.name);
        let ty = rust_field_type(&td.ty);
        let extra = if td.name == "PowerPortNumber" {
            quote! {
                /// `tms::INVALID_PORT_NUMBER` — the unspecified/invalid port sentinel.
                pub const INVALID_PORT_NUMBER: PowerPortNumber = -1;
            }
        } else {
            quote! {}
        };
        quote! {
            pub type #name = #ty;
            #extra
        }
    });
    quote! { #(#aliases)* }
}

// ---- name resolution ---------------------------------------------------------------------------

/// Simple type names declared in more than one module leaf (the `ac`/`dc` collisions).
pub(crate) fn colliding_names(model: &Model) -> HashSet<String> {
    let mut by_name: HashMap<&str, HashSet<&str>> = HashMap::new();
    for t in &model.types {
        by_name
            .entry(&t.name)
            .or_default()
            .insert(module_leaf(&t.module));
    }
    by_name
        .into_iter()
        .filter(|(_, mods)| mods.len() > 1)
        .map(|(n, _)| n.to_string())
        .collect()
}

fn module_leaf(module: &str) -> &str {
    module.rsplit("::").next().unwrap_or(module)
}

fn cap_first(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_ascii_uppercase().to_string() + c.as_str(),
        None => String::new(),
    }
}

/// The Rust type name for a declared type: bare IDL name, or `<Leaf><Name>` if the simple name
/// collides across `ac`/`dc`.
pub(crate) fn rust_type_name(module: &str, simple: &str, colliding: &HashSet<String>) -> String {
    if colliding.contains(simple) {
        format!("{}{}", cap_first(module_leaf(module)), simple)
    } else {
        simple.to_string()
    }
}

/// The Rust type name a resolved `Ref` points at. The resolver qualifies a ref as `leaf::Name` iff
/// the target collides, bare `Name` otherwise — so this mirrors [`rust_type_name`] exactly.
fn ref_rust_name(refstr: &str) -> String {
    match refstr.rsplit_once("::") {
        Some((leaf, simple)) => format!("{}{}", cap_first(leaf), simple),
        None => refstr.to_string(),
    }
}

fn ty_ident(s: &str) -> Ident {
    Ident::new(s, Span::call_site())
}

/// A field/variant identifier, raw-escaped if it collides with a Rust keyword (serde still emits the
/// bare name, so byte-identity is preserved).
fn safe_ident(s: &str) -> Ident {
    match syn::parse_str::<Ident>(s) {
        Ok(id) => id,
        Err(_) => Ident::new_raw(s, Span::call_site()),
    }
}

// ---- field types -------------------------------------------------------------------------------

fn rust_field_type(ty: &RFieldType) -> TokenStream {
    match ty {
        RFieldType::F32 => quote!(f32),
        RFieldType::F64 => quote!(f64),
        RFieldType::U8 => quote!(u8),
        RFieldType::U16 => quote!(u16),
        RFieldType::U32 => quote!(u32),
        RFieldType::U64 => quote!(u64),
        RFieldType::I16 => quote!(i16),
        RFieldType::I32 => quote!(i32),
        RFieldType::Bool => quote!(bool),
        RFieldType::Str(n) => {
            let n = Literal::usize_unsuffixed(*n as usize);
            quote!(heapless::String<#n>)
        }
        RFieldType::Seq(elem, n) => {
            let e = rust_field_type(elem);
            let n = Literal::usize_unsuffixed(*n as usize);
            quote!(heapless::Vec<#e, #n>)
        }
        RFieldType::Ref(name) => {
            let id = ty_ident(&ref_rust_name(name));
            quote!(#id)
        }
    }
}

/// A required primitive scalar (`Copy`-able as a struct field with no allocation/nesting).
fn is_scalar(ty: &RFieldType) -> bool {
    matches!(
        ty,
        RFieldType::F32
            | RFieldType::F64
            | RFieldType::U8
            | RFieldType::U16
            | RFieldType::U32
            | RFieldType::U64
            | RFieldType::I16
            | RFieldType::I32
            | RFieldType::Bool
    )
}

fn field_tokens(f: &RField) -> TokenStream {
    let name = safe_ident(&f.name);
    let mut fty = rust_field_type(&f.ty);
    let serde_attrs = if f.optional {
        fty = quote!(Option<#fty>);
        quote! { #[serde(skip_serializing_if = "Option::is_none", default)] }
    } else {
        quote! {}
    };
    quote! {
        #serde_attrs
        pub #name: #fty
    }
}

// ---- enums -------------------------------------------------------------------------------------

fn emit_enum(t: &RType, colliding: &HashSet<String>) -> TokenStream {
    let name = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
    let idents = sanitize_variant_idents(t);
    let doc = format!(
        "`{}::{}` — {}:{}",
        t.module, t.name, "mil-std-3071_data_model.idl", t.idl_line
    );

    let variants = t.variants.iter().zip(&idents).map(|(v, id)| {
        let wire = &v.wire_name;
        quote! { #[serde(rename = #wire)] #id }
    });
    let arms = t.variants.iter().zip(&idents).map(|(v, id)| {
        let wire = &v.wire_name;
        quote! { #name::#id => #wire }
    });

    quote! {
        #[doc = #doc]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
        #[repr(u8)]
        pub enum #name {
            #(#variants),*
        }
        impl #name {
            /// The exact IDL wire token for this variant — the same string the derived `Serialize`
            /// emits. Lets the flat wire serializer render the token without a drift-prone literal.
            pub const fn wire_str(self) -> &'static str {
                match self {
                    #(#arms),*
                }
            }
        }
    }
}

/// Rust variant identifiers for an enum, keyword-escaped + de-duplicated (the JSON wire spelling is
/// the serde rename, so the Rust identifier is free to be sanitized without affecting output).
fn sanitize_variant_idents(t: &RType) -> Vec<Ident> {
    let mut seen: HashSet<String> = HashSet::new();
    let mut out = Vec::new();
    for v in &t.variants {
        let mut base = v.rust_name.clone();
        if base.is_empty() || base == "Self" {
            base = format!("V{}", v.ordinal);
        }
        let mut nm = base.clone();
        let mut i = 2;
        while seen.contains(&nm) {
            nm = format!("{base}{i}");
            i += 1;
        }
        seen.insert(nm.clone());
        out.push(safe_ident(&nm));
    }
    out
}

// ---- structs -----------------------------------------------------------------------------------

fn emit_struct(t: &RType, colliding: &HashSet<String>) -> Result<TokenStream, String> {
    let name = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
    let doc = format!(
        "`{}::{}` — {}:{}",
        t.module, t.name, "mil-std-3071_data_model.idl", t.idl_line
    );
    let fields = t.fields.iter().map(field_tokens);

    // Derive `Copy` for an all-scalar struct (every field a required primitive — no `Option`, no
    // string/sequence, no nested struct ref). This restores golden's `Copy` on the small
    // value-carrying structs consumers pass around by value (`ClockMonotonic`, `Point2D`, …) without
    // it, a `ClockMonotonic` timestamp threaded into two topic payloads would be a use-after-move. A
    // struct with any `Option`/string/sequence/nested field stays non-`Copy` (e.g. `StorageCellState`,
    // now `Option<f32>` per #278 — the documented drop).
    let all_scalar = t.fields.iter().all(|f| !f.optional && is_scalar(&f.ty));
    let derive = if all_scalar {
        quote! { #[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)] }
    } else {
        quote! { #[derive(Debug, Clone, PartialEq, Serialize, Deserialize)] }
    };

    let struct_def = quote! {
        #[doc = #doc]
        #derive
        pub struct #name {
            #(#fields),*
        }
    };

    let tms_topic = if t.topics.is_empty() {
        quote! {}
    } else {
        let primary = &t.topics[0];
        let primary_id = topic_variant_ident(primary);
        let idl_line = t.idl_line;
        let topics_override = if t.topics.len() > 1 {
            let ts = t.topics.iter();
            quote! {
                fn topics() -> &'static [&'static str] {
                    &[#(#ts),*]
                }
            }
        } else {
            quote! {}
        };
        quote! {
            impl TmsTopic for #name {
                const TOPIC_ID: TmsTopicId = TmsTopicId::#primary_id;
                const TOPIC: &'static str = #primary;
                const IDL_LINE: u32 = #idl_line;
                #topics_override
            }
        }
    };

    Ok(quote! { #struct_def #tms_topic })
}

// ---- topic identity ----------------------------------------------------------------------------

/// The distinct topic-name strings across the whole model, in declaration order (the stable index).
fn ordered_topics(model: &Model) -> Vec<String> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for t in &model.types {
        for topic in &t.topics {
            if seen.insert(topic.clone()) {
                out.push(topic.clone());
            }
        }
    }
    out
}

fn topic_variant_ident(topic: &str) -> Ident {
    safe_ident(topic)
}

/// `#[repr(u8)] enum TmsTopicId` — the ONLY in-memory topic identity (one byte). The topic string is
/// materialized only at an I/O boundary (`as_str` out, `from_str` in).
fn emit_topic_id(model: &Model) -> Result<TokenStream, String> {
    let topics = ordered_topics(model);
    if topics.is_empty() {
        return Err("no @topic types found".into());
    }
    let variants = topics.iter().enumerate().map(|(i, t)| {
        let id = topic_variant_ident(t);
        let disc = Literal::u8_unsuffixed(i as u8);
        quote! { #id = #disc }
    });
    let as_str_arms = topics.iter().map(|t| {
        let id = topic_variant_ident(t);
        quote! { TmsTopicId::#id => #t }
    });
    let from_str_arms = topics.iter().map(|t| {
        let id = topic_variant_ident(t);
        quote! { #t => Some(TmsTopicId::#id) }
    });
    let all = topics.iter().map(|t| {
        let id = topic_variant_ident(t);
        quote! { TmsTopicId::#id }
    });
    let count = Literal::usize_unsuffixed(topics.len());

    Ok(quote! {
        /// The canonical in-memory topic identity — a `#[repr(u8)]` index. Topic STRINGS are held
        /// nowhere on the hot path; they are rendered on demand at I/O boundaries via
        /// [`TmsTopicId::as_str`] (out) / [`TmsTopicId::from_str`] (in).
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        #[repr(u8)]
        pub enum TmsTopicId {
            #(#variants),*
        }

        impl TmsTopicId {
            /// Every topic index, in declaration order (the stable discriminant order).
            pub const ALL: &'static [TmsTopicId] = &[#(#all),*];

            /// The number of distinct TMS topics.
            pub const COUNT: usize = #count;

            /// The DDS topic-name string for this index (materialized only on output).
            pub const fn as_str(self) -> &'static str {
                match self {
                    #(#as_str_arms),*
                }
            }

            /// Parse an inbound topic string back to its 1-byte index ("bring the index back").
            pub fn from_str(s: &str) -> Option<Self> {
                match s {
                    #(#from_str_arms,)*
                    _ => None,
                }
            }
        }
    })
}

// ---- factory ------------------------------------------------------------------------------------

/// Topic-bearing struct types (those with an `@topic`), in declaration order.
fn topic_types<'a>(model: &'a Model) -> Vec<&'a RType> {
    model
        .types
        .iter()
        .filter(|t| t.kind == RKind::Struct && !t.topics.is_empty())
        .collect()
}

/// `enum TmsMessage` — the topic->concrete-type dispatch factory.
///
/// HOST-ONLY (`std`): the enum holds every concrete topic type, so its size is the largest variant
/// (~200 KB) — an MCU RAM footgun if constructed on a 64 KB device, and it needs `serde_json`/`alloc`
/// to be useful anyway. The MCU dispatches via `TmsTopicId` + `WireFlat` instead, which don't need
/// this enum. Variants are `Box`ed so the enum itself is pointer-sized and only one concrete value
/// materializes transiently during `decode`.
fn emit_factory(model: &Model, colliding: &HashSet<String>) -> Result<TokenStream, String> {
    let types = topic_types(model);

    let variants = types.iter().map(|t| {
        let n = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
        quote! { #n(alloc::boxed::Box<#n>) }
    });
    let topic_arms = types.iter().map(|t| {
        let n = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
        quote! { TmsMessage::#n(_) => <#n as TmsTopic>::TOPIC_ID }
    });
    let idl_line_arms = types.iter().map(|t| {
        let n = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
        quote! { TmsMessage::#n(_) => <#n as TmsTopic>::IDL_LINE }
    });

    // decode: every topic string (incl. the summary/alias topics) dispatches to its owning type's
    // `#[inline(never)]` helper. The split keeps `decode`'s own frame tiny — otherwise a debug build
    // reserves the SUM of all 37 arms' `from_slice` frames (the largest topic type is ~200 KB), which
    // overflows the stack. CLAUDE.md: split divergent-cost match arms into `#[inline(never)]` fns.
    let decode_arms = model
        .types
        .iter()
        .filter(|t| t.kind == RKind::Struct && !t.topics.is_empty())
        .flat_map(|t| {
            let rn = rust_type_name(&t.module, &t.name, colliding);
            let helper = safe_ident(&format!("decode_{}", to_snake(&rn)));
            t.topics.iter().map(move |topic| {
                let id = topic_variant_ident(topic);
                let helper = helper.clone();
                quote! { TmsTopicId::#id => Self::#helper(bytes) }
            })
        });
    let decode_helpers = types.iter().map(|t| {
        let n = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
        let helper = safe_ident(&format!(
            "decode_{}",
            to_snake(&rust_type_name(&t.module, &t.name, colliding))
        ));
        quote! {
            #[inline(never)]
            fn #helper(bytes: &[u8]) -> Result<Self, DecodeError> {
                Ok(TmsMessage::#n(alloc::boxed::Box::new(
                    serde_json::from_slice(bytes).map_err(|_| DecodeError::Json)?
                )))
            }
        }
    });
    let encode_arms = types.iter().map(|t| {
        let n = ty_ident(&rust_type_name(&t.module, &t.name, colliding));
        quote! {
            TmsMessage::#n(v) => serde_json::to_string(&**v).map_err(|_| DecodeError::Json)
        }
    });

    Ok(quote! {
        /// The topic -> concrete-type dispatch factory: one variant per `@topic` type (HOST-only,
        /// `std`; variants `Box`ed — see the generator doc for why the MCU does not use this enum).
        #[cfg(feature = "std")]
        #[derive(Debug, Clone, PartialEq)]
        pub enum TmsMessage {
            #(#variants),*
        }

        #[cfg(feature = "std")]
        impl TmsMessage {
            /// This message's 1-byte topic identity.
            pub fn topic(&self) -> TmsTopicId {
                match self {
                    #(#topic_arms),*
                }
            }

            /// The topic string, rendered on demand from the enum identity.
            pub fn topic_str(&self) -> &'static str {
                self.topic().as_str()
            }

            /// The IDL source line of this message's type (provenance).
            pub fn idl_line(&self) -> u32 {
                match self {
                    #(#idl_line_arms),*
                }
            }

            /// Decode inbound JSON `bytes` published on `topic` into the concrete type. Maps the topic
            /// string to its 1-byte index at the boundary, then dispatches by the index.
            pub fn decode(topic: &str, bytes: &[u8]) -> Result<Self, DecodeError> {
                let id = TmsTopicId::from_str(topic).ok_or(DecodeError::UnknownTopic)?;
                match id {
                    #(#decode_arms,)*
                    #[allow(unreachable_patterns)]
                    _ => Err(DecodeError::UnknownTopic),
                }
            }

            #(#decode_helpers)*

            /// Encode this message to JSON. The value lives on the heap (`Box`), so serialization
            /// never materializes the ~200 KB struct on the stack.
            pub fn encode(&self) -> Result<alloc::string::String, DecodeError> {
                match self {
                    #(#encode_arms),*
                }
            }
        }
    })
}

fn to_snake(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::with_capacity(s.len() + 4);
    for (i, &c) in chars.iter().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 && (chars[i - 1].is_ascii_lowercase() || chars[i - 1].is_ascii_digit()) {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}
